use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_ids = input.as_array().unwrap().iter().map(|pair| {
        (pair[1], pair[0])
    }).collect::<Vec<(i64, i64)>>();

    sorted_ids.sort_by(|a, b| {
        if a.0 == b.0 {
            a.1.cmp(&b.1)
        } else {
            b.0.cmp(&a.0)
        }
    });

    serde_json::Value::Array(sorted_ids.into_iter().map(|(id, priority)| serde_json::Value::Number(id as f64)).collect())
}
